#include <iostream>

int main() {
    std::ios::sync_with_stdio(false);
    std::cin.tie(nullptr);
    int t;
    std::cin >> t;
    while (t--) {
        int n;
        std::cin >> n;
        long long sum = 0, best = 0;
        for (int i = 0; i < n; i++) {
            long long x;
            std::cin >> x;
            sum += x;
            if (i == 0 || x > best) best = x;
        }
        std::cout << sum << ' ' << best << '\n';
    }
}
